ALTER TABLE merchant ADD COLUMN closed_at timestamptz;
CREATE FUNCTION merchant_closed_time() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.status='CLOSED' AND OLD.status<>'CLOSED' THEN NEW.closed_at:=now(); ELSIF OLD.closed_at IS NOT NULL THEN NEW.closed_at:=OLD.closed_at; END IF; RETURN NEW; END $$;
CREATE TRIGGER merchant_closed_time BEFORE UPDATE ON merchant FOR EACH ROW EXECUTE FUNCTION merchant_closed_time();
CREATE TABLE purge_receipt(id uuid PRIMARY KEY,merchant_id uuid NOT NULL,maker_id uuid NOT NULL,checker_id uuid,phase varchar(30) NOT NULL DEFAULT 'PROPOSED',inventory text NOT NULL,fingerprint char(64) NOT NULL,backup_inventory text NOT NULL,provider_hash char(64) NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),approved_at timestamptz,completed_at timestamptz,CHECK(checker_id IS NULL OR checker_id<>maker_id));
CREATE TABLE retired_merchant(merchant_id uuid PRIMARY KEY,purge_id uuid UNIQUE NOT NULL,retired_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE retired_operation_identity(provider_key varchar(128) PRIMARY KEY,merchant_id uuid NOT NULL,operation_id uuid NOT NULL,fingerprint char(64) NOT NULL,retired_at timestamptz NOT NULL DEFAULT now());
CREATE OR REPLACE FUNCTION immutable_history() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF TG_OP='DELETE' AND current_user='mprp_purge' AND current_setting('mprp.purge_merchant',true)=OLD.merchant_id::text AND EXISTS(SELECT 1 FROM retired_merchant WHERE merchant_id=OLD.merchant_id) THEN RETURN OLD; END IF; RAISE EXCEPTION 'Immutable financial history' USING ERRCODE='23514'; END $$;
CREATE OR REPLACE FUNCTION source_guard() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF TG_OP='DELETE' THEN IF current_user='mprp_purge' AND current_setting('mprp.purge_merchant',true)=OLD.merchant_id::text AND EXISTS(SELECT 1 FROM retired_merchant WHERE merchant_id=OLD.merchant_id) THEN RETURN OLD; END IF; RAISE EXCEPTION 'Immutable source identity'; END IF; IF (NEW.id,NEW.merchant_id,NEW.provider_source_id,NEW.event_type,NEW.amount_minor,NEW.occurred_at,NEW.resource_id,NEW.posting_month) IS DISTINCT FROM (OLD.id,OLD.merchant_id,OLD.provider_source_id,OLD.event_type,OLD.amount_minor,OLD.occurred_at,OLD.resource_id,OLD.posting_month) OR (OLD.batch_id IS NOT NULL AND NEW.batch_id IS DISTINCT FROM OLD.batch_id) OR (OLD.recognized AND NOT NEW.recognized) THEN RAISE EXCEPTION 'Immutable source identity'; END IF; RETURN NEW; END $$;
CREATE OR REPLACE FUNCTION immutable_allocation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF current_user='mprp_purge' AND current_setting('mprp.purge_merchant',true)=(SELECT merchant_id::text FROM match_group WHERE id=OLD.group_id) THEN RETURN OLD; END IF; RAISE EXCEPTION 'allocation history is immutable'; END $$;
CREATE OR REPLACE FUNCTION immutable_report() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF TG_OP='DELETE' AND current_user='mprp_purge' AND current_setting('mprp.purge_merchant',true)=OLD.merchant_id::text THEN RETURN OLD; END IF; IF TG_OP='DELETE' OR NEW.snapshot_json<>OLD.snapshot_json OR NEW.snapshot_hash<>OLD.snapshot_hash THEN RAISE EXCEPTION 'report evidence immutable'; END IF; RETURN NEW; END $$;
UPDATE guard_registry g SET definition_hash=md5(pg_get_triggerdef(t.oid)||pg_get_functiondef(t.tgfoid)) FROM pg_trigger t WHERE t.tgname=g.name;
GRANT SELECT,INSERT,UPDATE ON purge_receipt TO mprp_runtime;
GRANT SELECT ON retired_merchant,retired_operation_identity TO mprp_runtime;
DO $$ BEGIN IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname='mprp_purge') THEN GRANT USAGE ON SCHEMA public TO mprp_purge; GRANT SELECT,INSERT,UPDATE,DELETE ON ALL TABLES IN SCHEMA public TO mprp_purge; REVOKE CREATE ON SCHEMA public FROM mprp_purge; END IF; END $$;
